  218: /// This machine's log folder in the per-user folder `config_dir`, after
  219: /// finishing any log an earlier, killed command left there (a running
  220: /// command's log is left alone). Blocking.
  221: pub fn logs_dir(config_dir: &std::path::Path) -> std::path::PathBuf {
  222:     let logs = config_dir.join("jobs").join("logs");
  223:     for problem in job_log::recover(&logs).problems {
  224:         log::warn!("job log recovery: {problem}");
  225:     }
  226:     logs
  227: }
