  229: /// The command's transfer options, in words, for its log's `run-start`.
  230: fn option_words(args: &TransferArgs) -> Vec<String> {
  231:     let mut words = Vec::new();
  232:     let flags = [
  233:         (args.dry_run, "dry-run"),
  234:         (args.checksum, "checksum"),
  235:         (args.size_only, "size-only"),
  236:         (args.ignore_times, "ignore-times"),
  237:         (args.ignore_existing, "ignore-existing"),
  238:         (args.force, "force"),
  239:         (args.resume, "resume"),
  240:         (args.detach, "detach"),
  241:         (args.null, "null"),
  242:     ];
  243:     words.extend(
  244:         flags
  245:             .iter()
  246:             .filter(|(on, _)| *on)
  247:             .map(|(_, word)| word.to_string()),
  248:     );
  249:     words.extend(args.include.iter().map(|glob| format!("include={glob}")));
  250:     words.extend(args.exclude.iter().map(|glob| format!("exclude={glob}")));
  251:     if args.retries > 0 {
  252:         words.push(format!("retries={}", args.retries));
  253:     }
  254:     if args.retry > 0 {
  255:         words.push(format!("retry={}", args.retry));
  256:     }
  257:     words
  258: }
