  260: /// A local run's final account, for its log.
  261: pub fn totals_from_local(summary: &blit_core::transfer_session::LocalMirrorSummary) -> RunTotals {
  262:     RunTotals {
  263:         files_copied: summary.copied_files as u64,
  264:         files_deleted: (summary.deleted_files + summary.deleted_dirs) as u64,
  265:         files_failed: summary.files_failed,
  266:         bytes_copied: summary.total_bytes,
  267:         files_resumed: 0,
  268:         in_stream_carrier: None,
  269:         failed_paths: summary.failed_paths.clone(),
  270:         failed_paths_truncated: summary.failed_paths_truncated,
  271:         failures: summary
  272:             .failures
  273:             .iter()
  274:             .map(|failure| (failure.relative_path.clone(), failure.reason.clone()))
  275:             .collect(),
  276:     }
  277: }
