 1009: /// How many events the audit lane holds before a producer waits.
 1010: pub const AUDIT_LANE_DEPTH: usize = 1024;
 1011: 
 1012: /// The sending end of an audit lane (JOB_LOGS, review cr-jl1b-2): the facts
 1013: /// a job log keeps — each file landed, sent, failed or deleted, and the
 1014: /// phase changes — on a bounded lane of their own, so a producer waits
 1015: /// while the log falls behind instead of a queue growing without bound.
 1016: /// The UI lane stays unbounded and best-effort. Planned totals are shared
 1017: /// counters, not events: they only ever add up.
 1018: #[derive(Clone)]
 1019: pub struct AuditSender {
 1020:     tx: flume::Sender<ProgressEvent>,
 1021:     planned: Arc<PlannedTotals>,
 1022: }
 1023: 
 1024: /// The receiving end of an audit lane; see [`audit_lane`].
 1025: pub struct AuditReceiver {
 1026:     rx: flume::Receiver<ProgressEvent>,
 1027:     planned: Arc<PlannedTotals>,
 1028: }
 1029: 
 1030: /// The files and bytes the destination's diff decided to send so far.
 1031: #[derive(Debug, Default)]
 1032: pub struct PlannedTotals {
 1033:     files: AtomicU64,
 1034:     bytes: AtomicU64,
 1035: }
 1036: 
 1037: impl PlannedTotals {
 1038:     pub fn get(&self) -> (u64, u64) {
 1039:         (
 1040:             self.files.load(Ordering::Relaxed),
 1041:             self.bytes.load(Ordering::Relaxed),
 1042:         )
 1043:     }
 1044: }
 1045: 
 1046: /// A new audit lane holding at most `capacity` events.
 1047: pub fn audit_lane(capacity: usize) -> (AuditSender, AuditReceiver) {
 1048:     let (tx, rx) = flume::bounded(capacity);
 1049:     let planned = Arc::new(PlannedTotals::default());
 1050:     (
 1051:         AuditSender {
 1052:             tx,
 1053:             planned: Arc::clone(&planned),
 1054:         },
 1055:         AuditReceiver { rx, planned },
 1056:     )
 1057: }
 1058: 
 1059: impl AuditReceiver {
 1060:     /// The next event; `None` once every sender is gone and the lane is
 1061:     /// drained.
 1062:     pub async fn recv(&self) -> Option<ProgressEvent> {
 1063:         self.rx.recv_async().await.ok()
 1064:     }
 1065: 
 1066:     pub fn planned(&self) -> Arc<PlannedTotals> {
 1067:         Arc::clone(&self.planned)
 1068:     }
 1069: }
 1070: 
 1071: #[derive(Clone)]
 1072: pub struct RemoteTransferProgress {
 1073:     sender: UnboundedSender<ProgressEvent>,
 1074:     /// The audit lane a job log reads, when one is attached.
 1075:     audit: Option<AuditSender>,
 1076:     /// Whether anything reads the UI lane; false for a handle made only to
 1077:     /// feed a log ([`audit_only`](Self::audit_only)).
 1078:     ui: bool,
 1079: }
 1080: 
 1081: /// Hand-written so option structs that carry a sink (e.g.
 1082: /// `LocalMirrorOptions`) keep their `Debug` derive without exposing
 1083: /// channel internals.
 1084: impl std::fmt::Debug for RemoteTransferProgress {
 1085:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 1086:         f.write_str("RemoteTransferProgress")
 1087:     }
 1088: }
