  261:     /// The lane watches the end the log's role names: a source sends, a
  262:     /// destination receives. An initiator, which is either, says which with
  263:     /// [`audit_lane_at`](Self::audit_lane_at).
  264:     pub fn audit_lane(&self) -> Option<AuditSender> {
