  274:     fn lane(&self, end: Option<End>) -> Option<AuditSender> {
  275:         let mut state = self.state();
  276:         state.place.as_ref()?;
  277:         let (sender, receiver) = audit_lane(AUDIT_LANE_DEPTH);
  278:         let planned = receiver.planned();
  279:         let log = self.clone();
  280:         let earlier = state.relay.take();
  281:         state.planned = Some(planned);
  282:         state.relay = Some(tokio::spawn(async move {
  283:             // One lane at a time, in order: an earlier pass's events land
  284:             // before this one's.
  285:             if let Some(earlier) = earlier {
  286:                 let _ = earlier.await;
  287:             }
  288:             while let Some(event) = receiver.recv().await {
  289:                 log.observe_from(&event, end).await;
  290:             }
  291:         }));
  292:         Some(sender)
  293:     }
